    'priv.updated': 'Última actualización: 29 de xuño de 2026',
    'priv.intro': 'Esta política describe como <strong>Crintech Studios</strong> ("nós") trata a información cando usas <em>Kaixo</em>, xa sexa na web <a href="https://euskera.crintech.pro" rel="noopener">euskera.crintech.pro</a>, na aplicación para iOS (App Store) ou na aplicación Android (proximamente en Google Play) — en diante, "o Servizo".',
