    'priv.s1.li1': '<strong>Sen contas.</strong> Non necesitas rexistrarte nin iniciar sesión. Non che pedimos nome, correo electrónico, teléfono nin ningún outro dato identificativo.',
    'priv.s1.li2': '<strong>Sen analítica nin tracking.</strong> Non usamos Google Analytics, Cloudflare Web Analytics, Plausible, Umami, Meta Pixel nin ningún SDK de terceiros para medir audiencia, xerar perfís ou mostrar publicidade.',
    'priv.s1.li3': '<strong>Sen fingerprinting.</strong> Non usamos pegadas dixitais do navegador nin técnicas de tracking entre sitios.',
    'priv.s1.li4': '<strong>Sen publicidade.</strong> O Servizo é gratuíto e libre de anuncios.',
    'priv.s2.title': '2. Almacenamento local no teu dispositivo',
    'priv.s2.p1': 'O teu progreso vive unicamente no navegador ou na app, usando <code>localStorage</code>. Isto inclúe: leccións completadas, exercicios acertados, logros desbloqueados, idioma seleccionado, estado do Modo Expedición e a marca de paso pola páxina "Sobre".',
    'priv.s2.p2': '<strong>Estes datos nunca saen do teu dispositivo</strong>. Non os enviamos a ningún servidor. Se cambias de dispositivo, podes exportar o teu progreso como un código que pegas no novo dispositivo para restauralo — ti decides cando e onde compartilo.',
    'priv.s2.p3': 'Ao ser estritamente necesarias para que a aplicación funcione, este tipo de almacenamento non require un aviso de consentimento baixo a Directiva ePrivacy europea nin as guías da AEPD.',
    'priv.s3.title': '3. Aloxamento e conexións de rede',
    'priv.s3.p1': 'A web e os ficheiros estáticos da app sérvense desde <strong>Cloudflare Pages</strong>. Coma calquera servidor web, Cloudflare rexistra peticións HTTP que poden incluír IP, data e user agent, co fin exclusivo de protexer o Servizo (mitigación de abuso, CDN, métricas agregadas de tráfico). Non temos acceso a estes rexistros individualmente e non os enlazamos con ningunha identidade. Podes consultar a súa política en <a href="https://www.cloudflare.com/privacypolicy/" rel="noopener">cloudflare.com/privacypolicy</a>.',
    'priv.s3.p2': 'A aplicación para iOS é un contedor lixeiro que carga a mesma web dentro dun <strong>WebView</strong> do sistema; a aplicación Android, cando se publique, será un <strong>Trusted Web Activity (TWA)</strong> equivalente sobre Chrome. En ningún caso se envían datos adicionais por usar a app no canto da web.',
    'priv.s4.title': '4. Servizos de terceiros',
    'priv.s4.intro': 'O Servizo non integra ningún SDK nin servizo de terceiros que reciba datos persoais. As únicas conexións saíntes son:',
    'priv.s4.li1': '<strong>Tipografías</strong> Manrope e Fraunces, autoaloxadas desde o mesmo dominio (non Google Fonts).',
    'priv.s4.li2': '<strong>GitHub</strong> unicamente se fas clic nunha ligazón ao repositorio. A visita queda suxeita á <a href="https://docs.github.com/site-policy/privacy-policies/github-privacy-statement" rel="noopener">política de GitHub</a>.',
    'priv.s4.li3': '<strong>App Store</strong> unicamente para a descarga e instalación da app de iOS, suxeita á política de Apple.',
    'priv.s4.li4': '<strong>Google Play</strong>, cando a app Android estea dispoñible, unicamente para a súa descarga e instalación, suxeita á política de Google.',
    'priv.s5.title': '5. Sistema de feedback',
    'priv.s5.intro': 'Se nos envías un informe a través da páxina de <a href="/{0}/feedback/">Feedback</a>, recollemos os seguintes datos no noso backend (non no teu dispositivo):',
    'priv.s5.li1': '<strong>Obrigatorios:</strong> título e descrición do informe (o que ti escribes), tipo (bug / suxestión / etc.).',
    'priv.s5.li2': '<strong>Opcionais:</strong> correo electrónico e/ou nome de Discord, unicamente se ti decides escribilos nos campos correspondentes para que poidamos responderche. Se os deixas baleiros, non se recolle ningún identificador.',
    'priv.s5.li3': '<strong>Técnicos:</strong> o URL relativo da páxina desde a que se enviou e un fragmento do user agent (máximo 200 caracteres), para reproducir bugs.',
    'priv.s5.li4': '<strong>Antibot:</strong> un token de <a href="https://www.cloudflare.com/products/turnstile/" rel="noopener">Cloudflare Turnstile</a> emitido por Cloudflare, que verifica que non es un bot. Desbótase inmediatamente tras a validación.',
    'priv.s5.outro': 'Estes datos úsanse unicamente para xestionar o tícket e, se nos deixaches contacto, para responderche. Non os compartimos con terceiros e podes pedir o seu borrado en calquera momento escribíndonos ao correo máis abaixo.',
    'priv.s6.title': '6. Persoas menores de idade',
    'priv.s6.body': 'Kaixo non está dirixida especificamente a persoas menores de 13 anos, nin recolle datos sobre elas. Non usamos pasarelas de identificación de idade precisamente porque non necesitamos ningún dato persoal.',
    'priv.s7.title': '7. Os teus dereitos (RXPD)',
    'priv.s7.body': 'Como non almacenamos datos persoais identificables nos nosos sistemas, os dereitos clásicos de acceso, rectificación, supresión, oposición, portabilidade e limitación exércense na práctica desde o propio dispositivo: borrando os datos do navegador ou desinstalando a app. Aínda así, se tes calquera consulta ou cres que algún dato che concirne, podes escribirnos.',
    'priv.s8.title': '8. Cambios nesta política',
    'priv.s8.body': 'Se esta política cambia (por exemplo, se no futuro engadísemos algún servizo adicional), actualizaremos a data na parte superior e, se o cambio fose material, anunciarémolo tamén na páxina de inicio e nas notas de versión do repositorio.',
    'priv.s9.title': '9. Contacto',
    'fbp.eyebrow': 'Tíckets',
    'fbp.title': 'Hai algo que <span class="text-grad">contar</span>.',
    'fbp.lead': 'Bugs, suxestións, erros nunha lección, traducións que coxean, dúbidas concretas. O que sexa. Cada tícket chéganos e xestiónase desde o noso Discord.',
    'fbp.how.title': 'Como funciona?',
    'fbp.how.li1': 'Elixes a categoría que mellor describe o asunto.',
    'fbp.how.li2': 'Descríbelo co detalle que teñas — pasos, capturas mentais, contexto.',
    'fbp.how.li3': 'Se queres resposta, deixas o teu correo ou usuario de Discord.',
    'fbp.how.li4': 'Recibes un ID público. Se deixaches contacto, avisámoste cando o pechemos.',
    'fbp.note': 'Non hai backend de contas. Non gardamos historiais ligados a ti. O ID que recibes é o único que necesitas para seguir o tícket.',
