    "sources.statement": "Lo curriculum sigue los estándars CEFR oficials ta los libels A1-C2 d'o basco. As explicacions, eixemplos y exercicios son material orichinal. Vocabulario y reglas gramaticals son feitos lingüisticos de dominio publico.",
