    'about.license.content': 'Conținut: <a href="https://github.com/Crinlorite/euskera-static/blob/main/LICENSE-CONTENT" rel="noopener">CC BY-SA 4.0</a> — liber de utilizat, partajat și adaptat cu atribuire și sub aceeași licență.',
    'about.contribute.title': 'Contribuie',
    'about.contribute.body': 'Ai detectat o eroare? Ai idei? Deschide un issue sau un PR pe <a href="https://github.com/Crinlorite/euskera-static" rel="noopener">GitHub</a>. Traducerile în alte limbi sunt în mod special binevenite.',
    'priv.title': 'Politică de confidențialitate',
    'priv.updated': 'Ultima actualizare: 29 iunie 2026',
    'priv.intro': 'Această politică descrie cum <strong>Crintech Studios</strong> („noi”) tratează informațiile atunci când folosești <em>Kaixo</em>, fie pe site-ul <a href="https://euskera.crintech.pro" rel="noopener">euskera.crintech.pro</a>, în aplicația pentru iOS (App Store) sau în aplicația Android (în curând pe Google Play) — denumite în continuare „Serviciul”.',
    'priv.s1.title': '1. Informațiile pe care le colectăm',
    'priv.s1.intro': 'Kaixo este conceput pentru a nu colecta informații personale:',
    'priv.s1.li1': '<strong>Fără conturi.</strong> Nu trebuie să te înregistrezi sau să te autentifici. Nu îți cerem numele, e-mailul, telefonul sau orice altă dată de identificare.',
    'priv.s1.li2': '<strong>Fără analiză sau tracking.</strong> Nu folosim Google Analytics, Cloudflare Web Analytics, Plausible, Umami, Meta Pixel sau orice alt SDK terț pentru a măsura audiența, a genera profiluri sau a afișa publicitate.',
    'priv.s1.li3': '<strong>Fără fingerprinting.</strong> Nu folosim amprente digitale ale browserului sau tehnici de tracking între site-uri.',
    'priv.s1.li4': '<strong>Fără publicitate.</strong> Serviciul este gratuit și fără reclame.',
    'priv.s2.title': '2. Stocare locală pe dispozitivul tău',
    'priv.s2.p1': 'Progresul tău este salvat exclusiv în browser sau în aplicație, folosind <code>localStorage</code>. Acesta include: lecții finalizate, exerciții rezolvate corect, realizări deblocate, limba selectată, starea Modului Expediție și marcajul de vizitare a paginii „Despre”.',
    'priv.s2.p2': '<strong>Aceste date nu părăsesc niciodată dispozitivul tău</strong>. Nu le trimitem către niciun server. Dacă schimbi dispozitivul, poți exporta progresul sub forma unui cod pe care îl introduci pe noul dispozitiv pentru a-l restaura — tu decizi când și unde îl partajezi.',
    'priv.s2.p3': 'Fiind strict necesar pentru funcționarea aplicației, acest tip de stocare nu necesită un banner de consimțământ conform Directivei ePrivacy europene sau ghidurilor AEPD.',
    'priv.s3.title': '3. Găzduire și conexiuni de rețea',
    'priv.s3.p1': 'Site-ul web și fișierele statice ale aplicației sunt servite de pe <strong>Cloudflare Pages</strong>. Ca orice server web, Cloudflare înregistrează cereri HTTP care pot include IP-ul, data și user agent-ul, cu scopul exclusiv de a proteja Serviciul (atenuarea abuzurilor, CDN, metrici agregate de trafic). Nu avem acces individual la aceste jurnale și nu le asociem cu nicio identitate. Poți consulta politica lor la <a href="https://www.cloudflare.com/privacypolicy/" rel="noopener">cloudflare.com/privacypolicy</a>.',
    'priv.s3.p2': 'Aplicația pentru iOS este un container simplu care încarcă același site web într-un <strong>WebView</strong> de sistem; aplicația Android, când va fi publicată, va fi un <strong>Trusted Web Activity (TWA)</strong> echivalent, bazat pe Chrome. În niciun caz nu se trimit date suplimentare pentru utilizarea aplicației în loc de site-ul web.',
    'priv.s4.title': '4. Servicii terțe',
    'priv.s4.intro': 'Serviciul nu integrează niciun SDK sau serviciu terț care primește date personale. Singurele conexiuni externe sunt:',
    'priv.s4.li1': '<strong>Fonturile</strong> Manrope și Fraunces, auto-găzduite de pe același domeniu (nu Google Fonts).',
    'priv.s4.li2': '<strong>GitHub</strong>, doar dacă dai clic pe un link către repozitoriu. Vizita este supusă <a href="https://docs.github.com/site-policy/privacy-policies/github-privacy-statement" rel="noopener">politicii GitHub</a>.',
    'priv.s4.li3': '<strong>App Store</strong>, doar pentru descărcarea și instalarea aplicației iOS, supusă politicii Apple.',
    'priv.s4.li4': '<strong>Google Play</strong>, când aplicația Android va fi disponibilă, doar pentru descărcarea și instalarea sa, supusă politicii Google.',
    'priv.s5.title': '5. Sistem de feedback',
    'priv.s5.intro': 'Dacă ne trimiți un raport prin pagina de <a href="/{0}/feedback/">Feedback</a>, colectăm următoarele date în backend-ul nostru (nu pe dispozitivul tău):',
    'priv.s5.li1': '<strong>Obligatorii:</strong> titlul și descrierea raportului (ceea ce scrii tu), tipul (bug / sugestie / etc.).',
    'priv.s5.li2': '<strong>Opționale:</strong> e-mail și/sau nume de utilizator Discord, doar dacă decizi să le completezi în câmpurile corespunzătoare pentru a-ți putea răspunde. Dacă le lași goale, nu se colectează niciun identificator.',
    'priv.s5.li3': '<strong>Tehnice:</strong> URL-ul relativ al paginii de pe care a fost trimis și un fragment din user agent (maximum 200 de caractere), pentru a reproduce bug-uri.',
    'priv.s5.li4': '<strong>Anti-bot:</strong> un token <a href="https://www.cloudflare.com/products/turnstile/" rel="noopener">Cloudflare Turnstile</a> emis de Cloudflare, care verifică că nu ești un bot. Acesta este eliminat imediat după validare.',
    'priv.s5.outro': 'Aceste date sunt folosite exclusiv pentru a gestiona tichetul și, dacă ne-ai lăsat date de contact, pentru a-ți răspunde. Nu le partajăm cu terți și poți solicita ștergerea lor în orice moment, scriindu-ne la adresa de e-mail de mai jos.',
    'priv.s6.title': '6. Persoane minore',
    'priv.s6.body': 'Kaixo nu se adresează în mod specific persoanelor sub 13 ani și nici nu colectează date despre acestea. Nu folosim sisteme de verificare a vârstei tocmai pentru că nu avem nevoie de date personale.',
    'priv.s7.title': '7. Drepturile tale (GDPR)',
    'priv.s7.body': 'Deoarece nu stocăm date personale identificabile în sistemele noastre, drepturile clasice de acces, rectificare, ștergere, opoziție, portabilitate și limitare se exercită în practică direct de pe dispozitiv: ștergând datele din browser sau dezinstalând aplicația. Chiar și așa, dacă ai orice întrebare sau crezi că anumite date te privesc, ne poți scrie.',
    'priv.s8.title': '8. Modificări ale acestei politici',
    'priv.s8.body': 'Dacă această politică se modifică (de exemplu, dacă în viitor am adăuga un serviciu suplimentar), vom actualiza data din partea de sus și, dacă modificarea este substanțială, o vom anunța și pe pagina principală și în notele de versiune ale repozitoriului.',
    'priv.s9.title': '9. Contact',
    'fbp.eyebrow': 'Tichete',
    'fbp.title': 'Ai ceva de <span class="text-grad">spus</span>.',
    'fbp.lead': 'Bug-uri, sugestii, erori într-o lecție, traduceri care scârțâie, întrebări specifice. Orice. Fiecare tichet ajunge la noi și este gestionat de pe serverul nostru de Discord.',
    'fbp.how.title': 'Cum funcționează?',
    'fbp.how.li1': 'Alegi categoria care descrie cel mai bine subiectul.',
    'fbp.how.li2': 'Îl descrii cu detaliile pe care le ai — pași, capturi mentale, context.',
    'fbp.how.li3': 'Dacă vrei un răspuns, lași un e-mail sau un nume de utilizator Discord.',
    'fbp.how.li4': 'Primești un ID public. Dacă ai lăsat date de contact, te anunțăm când îl închidem.',
    'fbp.note': 'Nu există un backend pentru conturi. Nu salvăm istorice legate de tine. ID-ul pe care îl primești este singurul lucru de care ai nevoie pentru a urmări tichetul.',
    'fb.ok.email': 'Te vom anunța pe e-mail când ne ocupăm de el.',
