    'priv.title': '개인정보 처리방침',
    'priv.updated': '최종 업데이트: 2026년 6월 29일',
    'priv.intro': '이 방침은 귀하가 웹사이트 <a href="https://euskera.crintech.pro" rel="noopener">euskera.crintech.pro</a>, iOS 앱(App Store), 또는 안드로이드 앱(Google Play 출시 예정)을 통해 <em>Kaixo</em>를 이용할 때 <strong>Crintech Studios</strong>("당사")가 정보를 어떻게 처리하는지 설명합니다. 이하 통칭하여 "서비스"라 합니다.',
    'priv.s1.title': '1. 수집하는 정보',
    'priv.s1.intro': 'Kaixo는 개인 정보를 수집하지 않도록 설계되었습니다:',
    'priv.s1.li1': '<strong>계정 없음.</strong> 회원가입이나 로그인이 필요 없습니다. 이름, 이메일, 전화번호 등 어떠한 식별 정보도 요구하지 않습니다.',
    'priv.s1.li2': '<strong>분석 및 추적 없음.</strong> Google Analytics, Cloudflare Web Analytics, Plausible, Umami, Meta Pixel 등 사용자 측정, 프로파일링, 광고 표시를 위한 제3자 SDK를 사용하지 않습니다.',
    'priv.s1.li3': '<strong>핑거프린팅 없음.</strong> 브라우저 핑거프린팅이나 사이트 간 추적 기술을 사용하지 않습니다.',
    'priv.s1.li4': '<strong>광고 없음.</strong> 본 서비스는 무료이며 광고가 없습니다.',
    'priv.s2.title': '2. 기기 내 로컬 저장소',
    'priv.s2.p1': '학습 진행 상황은 <code>localStorage</code>를 사용하여 브라우저나 앱 내에만 저장됩니다. 여기에는 완료한 강의, 정답을 맞힌 연습 문제, 잠금 해제한 업적, 선택한 언어, 탐험 모드 상태, \'정보\' 페이지 방문 여부 등이 포함됩니다.',
    'priv.s2.p2': '<strong>이 데이터는 절대 기기 밖으로 나가지 않습니다</strong>. 당사는 어떤 서버로도 이 데이터를 전송하지 않습니다. 기기를 변경할 경우, 진행 상황을 코드로 내보내 새 기기에 붙여넣어 복원할 수 있습니다. 언제 어디서 공유할지는 전적으로 귀하가 결정합니다.',
    'priv.s2.p3': '이러한 유형의 저장소는 애플리케이션이 작동하는 데 반드시 필요하므로, 유럽 ePrivacy 지침 및 AEPD 가이드라인에 따라 동의 배너가 필요하지 않습니다.',
    'priv.s3.title': '3. 호스팅 및 네트워크 연결',
    'priv.s3.p1': '웹사이트와 앱의 정적 파일은 <strong>Cloudflare Pages</strong>를 통해 제공됩니다. 모든 웹 서버와 마찬가지로, Cloudflare는 서비스 보호(악용 완화, CDN, 집계된 트래픽 측정) 목적으로만 IP, 날짜, 사용자 에이전트(user agent)를 포함할 수 있는 HTTP 요청을 기록합니다. 당사는 이러한 개별 기록에 접근할 수 없으며, 이를 어떠한 신원과도 연결하지 않습니다. Cloudflare의 개인정보 처리방침은 <a href="https://www.cloudflare.com/privacypolicy/" rel="noopener">cloudflare.com/privacypolicy</a>에서 확인하실 수 있습니다.',
    'priv.s3.p2': 'iOS 앱은 시스템 <strong>WebView</strong> 내에서 동일한 웹사이트를 로드하는 가벼운 컨테이너입니다. 출시될 안드로이드 앱은 Chrome 기반의 동등한 <strong>Trusted Web Activity (TWA)</strong>가 될 것입니다. 웹 대신 앱을 사용한다고 해서 추가적인 데이터가 전송되는 경우는 없습니다.',
    'priv.s4.title': '4. 제3자 서비스',
    'priv.s4.intro': '본 서비스는 개인 데이터를 수신하는 어떠한 제3자 SDK나 서비스도 통합하지 않습니다. 유일한 외부 연결은 다음과 같습니다:',
    'priv.s4.li1': '<strong>글꼴</strong> Manrope와 Fraunces는 동일한 도메인에서 자체 호스팅됩니다(Google Fonts 아님).',
    'priv.s4.li2': '<strong>GitHub</strong>는 저장소 링크를 클릭할 경우에만 연결됩니다. 해당 방문은 <a href="https://docs.github.com/site-policy/privacy-policies/github-privacy-statement" rel="noopener">GitHub의 개인정보 처리방침</a>에 따릅니다.',
    'priv.s4.li3': '<strong>App Store</strong>는 iOS 앱 다운로드 및 설치 시에만 연결되며, Apple의 정책에 따릅니다.',
    'priv.s4.li4': '<strong>Google Play</strong>는 안드로이드 앱이 출시되면 다운로드 및 설치 시에만 연결되며, Google의 정책에 따릅니다.',
    'priv.s5.title': '5. 피드백 시스템',
    'priv.s5.intro': '<a href="/{0}/feedback/">피드백</a> 페이지를 통해 보고서를 제출하면, 당사는 다음 데이터를 백엔드(귀하의 기기가 아닌)에 수집합니다:',
    'priv.s5.li1': '<strong>필수:</strong> 보고서 제목 및 설명(귀하가 작성한 내용), 유형(버그/제안 등).',
    'priv.s5.li2': '<strong>선택:</strong> 이메일 및/또는 Discord 사용자 이름. 당사가 회신할 수 있도록 해당 필드에 직접 입력하기로 결정한 경우에만 수집됩니다. 비워두면 어떠한 식별자도 수집되지 않습니다.',
    'priv.s5.li3': '<strong>기술 정보:</strong> 버그 재현을 위해 보고서가 전송된 페이지의 상대 URL 및 사용자 에이전트(user agent) 일부(최대 200자).',
    'priv.s5.li4': '<strong>봇 방지:</strong> 귀하가 봇이 아님을 확인하는 Cloudflare에서 발급한 <a href="https://www.cloudflare.com/products/turnstile/" rel="noopener">Cloudflare Turnstile</a> 토큰. 확인 후 즉시 폐기됩니다.',
    'priv.s5.outro': '이 데이터는 티켓을 관리하고, 연락처를 남기신 경우 회신하는 데에만 사용됩니다. 제3자와 공유하지 않으며, 아래 이메일로 연락하여 언제든지 삭제를 요청할 수 있습니다.',
    'priv.s6.title': '6. 미성년자',
