    'priv.s7.title': '7. 귀하의 권리 (GDPR)',
    'priv.s7.body': '당사 시스템에는 식별 가능한 개인 데이터를 저장하지 않으므로, 접근, 정정, 삭제, 반대, 이동, 처리 제한과 같은 전통적인 권리는 사실상 기기 자체에서 브라우저 데이터를 삭제하거나 앱을 제거함으로써 행사됩니다. 그럼에도 불구하고, 문의 사항이 있거나 데이터가 귀하와 관련이 있다고 생각되시면 언제든지 연락 주시기 바랍니다.',
